// TestEngineAtMatchesReplayToHeads pins the brief's equality gate: for a
// spread of intent counts, EngineAt's engine and a hand-rolled
// replay.ReplayTo over the same snapshot's (Log, Config) stand at the same
// head — the same replay by construction, not two code paths. The negative
// case is NOT tautological: EngineAt normalizes n<0 to len(Intents) itself
// (ReplayTo clamps negatives to genesis), so EngineAt(-1) is compared
// against the explicit full-intent ReplayTo — and asserted to actually be
// the capture point, not genesis.
func TestEngineAtMatchesReplayToHeads(t *testing.T) {
	requireCorpus(t)
	l, cfg, meta, err := feedback.Load(fixtureRel)
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	full, err := replay.Replay(l, cfg)
	if err != nil {
		t.Fatalf("full replay: %v", err)
	}
	for _, n := range []int{0, 1, 7, meta.IntentCount - 1, meta.IntentCount} {
		e1 := feedback.EngineAt(t, fixtureRel, n)
		e2, err := replay.ReplayTo(l, cfg, n)
		if err != nil {
			t.Fatalf("ReplayTo(%d): %v", n, err)
		}
		if e1.L.Head() != e2.L.Head() || len(e1.L.Events) != len(e2.L.Events) {
			t.Errorf("n=%d: EngineAt head %s (%d events), ReplayTo head %s (%d events)",
				n, e1.L.Head(), len(e1.L.Events), e2.L.Head(), len(e2.L.Events))
		}
	}
	neg := feedback.EngineAt(t, fixtureRel, -1)
	if neg.L.Head() != full.L.Head() || len(neg.L.Events) != len(full.L.Events) {
		t.Errorf("EngineAt(-1) head %s (%d events), full replay head %s (%d events)",
			neg.L.Head(), len(neg.L.Events), full.L.Head(), len(full.L.Events))
	}
	if neg.L.Head() != meta.Head {
		t.Errorf("EngineAt(-1) head %s is not the capture point (recorded %s)", neg.L.Head(), meta.Head)
	}
}

// TestReproOnFreshSnapshot runs the whole product on a snapshot captured
// live by the feedback capture's own code in this test — not the committed
// fixture — so the loader cannot drift from the capture shape without this
// failing. The corpus pin coupling the committed fixture carries does not
// apply here: the capture and the replay run against the same corpus.
func TestReproOnFreshSnapshot(t *testing.T) {
	requireCorpus(t)
	advance, r := gatedFixtureRegistry(t)
	advance(12)
	dir := t.TempDir()
	captureSnapshotFiles(t, r, dir)

	var out bytes.Buffer
	if code := run([]string{dir}, &out, io.Discard); code != 0 {
		t.Fatalf("exit %d, output:\n%s", code, out.String())
	}
	if !strings.Contains(out.String(), "replayed 21 of 21 recorded intents") {
		t.Errorf("fresh snapshot summary unexpected:\n%s", out.String())
	}
	out.Reset()
	if code := run([]string{"-list", dir}, &out, io.Discard); code != 0 {
		t.Fatalf("list exit %d, output:\n%s", code, out.String())
	}
}

// TestReproEmitTestSkeletonCompilesAndFailsOnTODO: -emit-test copies the
// snapshot into the target package's testdata and writes a test that
// compiles and fails only on its TODO. The target is a scratch package
// under the repo root (a real package the go tool builds), removed on
// cleanup.
func TestReproEmitTestSkeletonCompilesAndFailsOnTODO(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	scratch := filepath.Join(root, "zzrepro-emittest")
	t.Cleanup(func() { os.RemoveAll(scratch) })
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(scratch, "doc.go"), []byte("package emittmp\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-emittest", fixtureRel}, &out, io.Discard); code != 0 {
		t.Fatalf("emit exit %d, output:\n%s", code, out.String())
	}
	if _, err := os.Stat(filepath.Join(scratch, "testdata", "feedback", fixtureID, "match.json")); err != nil {
		t.Errorf("snapshot not copied: %v", err)
	}

	// The generated test is the target package's EXTERNAL test package —
	// feedback imports the engine tier, so an internal-package skeleton
	// would be an import cycle for any engine-side target. The declaration
	// (not the file name) is what makes it external.
	san := sanitize(fixtureID)
	raw, err := os.ReadFile(filepath.Join(scratch, "repro_feedback_"+san+"_test.go"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(raw), "package emittmp_test") {
		t.Errorf("generated skeleton is not the external test package:\n%s", raw)
	}

	// The generated test compiles and fails on its TODO, not on load.
	cmd := exec.Command("go", "test", "./zzrepro-emittest", "-run", "TestFeedbackRepro20260914T120000Z_fb01")
	cmd.Dir = root
	raw2, err := cmd.CombinedOutput()
	if err == nil {
		t.Fatalf("generated test passed; it must fail on the TODO:\n%s", raw2)
	}
	if !strings.Contains(string(raw2), "TODO: assert the reported behaviour") {
		t.Fatalf("generated test failed for another reason:\n%s", raw2)
	}
}

// TestReproEmitTestIntoRulesCompilesAndFailsOnTODO is the probe the scratch
// package cannot be: the NATURAL target for a repro test is an engine
// package (the reported behaviour lives in rules/), and an internal-package
// skeleton emitted there forms rules -> feedback -> rules — an import cycle
// the go toolchain refuses at setup. The skeleton is the external test
// package, so emitting into the real rules package must compile and fail
// only on the TODO. The file (and its copied snapshot) is removed on
// cleanup; the run compiles the rules test binary from the build cache
// because nothing in rules changed.
func TestReproEmitTestIntoRulesCompilesAndFailsOnTODO(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	san := sanitize(fixtureID)
	testPath := filepath.Join(root, "rules", "repro_feedback_"+san+"_test.go")
	dataDir := filepath.Join(root, "rules", "testdata", "feedback", fixtureID)
	// Only remove what this test created: rules/testdata is not ours if it
	// already carried content before the emit.
	testdataPreExisting := false
	if ents, err := os.ReadDir(filepath.Join(root, "rules", "testdata")); err == nil && len(ents) > 0 {
		testdataPreExisting = true
	}
	t.Cleanup(func() {
		os.Remove(testPath)
		os.RemoveAll(dataDir)
		if !testdataPreExisting {
			os.Remove(filepath.Join(root, "rules", "testdata", "feedback"))
			os.Remove(filepath.Join(root, "rules", "testdata"))
		}
	})

	var out bytes.Buffer
	if code := run([]string{"-emit-test", "rules", fixtureRel}, &out, io.Discard); code != 0 {
		t.Fatalf("emit exit %d, output:\n%s", code, out.String())
	}
	raw, err := os.ReadFile(testPath)
	if err != nil {
		t.Fatalf("skeleton not written into rules/: %v", err)
	}
	if !strings.Contains(string(raw), "package rules_test") {
		t.Fatalf("skeleton emitted into rules/ is not the external test package:\n%s", raw)
	}
	cmd := exec.Command("go", "test", "./rules", "-run", "^TestFeedbackRepro20260914T120000Z_fb01$")
	cmd.Dir = root
	res, err := cmd.CombinedOutput()
	if err == nil {
		t.Fatalf("emitted rules test passed; it must fail on the TODO:\n%s", res)
	}
	if !strings.Contains(string(res), "TODO: assert the reported behaviour") {
		t.Fatalf("emitted rules test failed for another reason:\n%s", res)
	}
}

// TestReproEmitTestRefusesOverwrite: a second emit at the same target is
// refused rather than clobbering a test someone may have filled in.
func TestReproEmitTestRefusesOverwrite(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	scratch := filepath.Join(root, "zzrepro-emittest2")
	t.Cleanup(func() { os.RemoveAll(scratch) })
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(scratch, "doc.go"), []byte("package emittmp\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-emittest2", fixtureRel}, &out, io.Discard); code != 0 {
		t.Fatalf("first emit exit %d:\n%s", code, out.String())
	}
	// Simulate a filled-in test and a hand-refreshed snapshot: the refused
	// second emit must leave both byte-identical, not just exit non-zero.
	san := sanitize(fixtureID)
	testPath := filepath.Join(scratch, "repro_feedback_"+san+"_test.go")
	logPath := filepath.Join(scratch, "testdata", "feedback", fixtureID, "log.json")
	filledTest := []byte("package emittmp_test\n\n// filled in by hand\n")
	editedLog := []byte(`{"edited":"by hand"}`)
	if err := os.WriteFile(testPath, filledTest, 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(logPath, editedLog, 0o644); err != nil {
		t.Fatal(err)
	}
	out.Reset()
	if code := run([]string{"-emit-test", "zzrepro-emittest2", fixtureRel}, &out, io.Discard); code == 0 {
		t.Fatalf("second emit overwrote the first:\n%s", out.String())
	}
	if got, _ := os.ReadFile(testPath); !bytes.Equal(got, filledTest) {
		t.Errorf("refused emit rewrote the test file:\n%s", got)
	}
	if got, _ := os.ReadFile(logPath); !bytes.Equal(got, editedLog) {
		t.Errorf("refused emit rewrote the snapshot's log.json:\n%s", got)
	}
}

// TestReproEmitTestRejectsTamperedCapture: -emit-test verifies the complete
// capture before writing. A log.json whose head alone was corrupted exits
// non-zero with DIVERGED and creates neither the snapshot copy nor the
// skeleton.
func TestReproEmitTestRejectsTamperedCapture(t *testing.T) {
	requireCorpus(t)
	root, err := feedback.Root()
	if err != nil {
		t.Skipf("no repo root: %v", err)
	}
	scratch := filepath.Join(root, "zzrepro-emittest3")
	t.Cleanup(func() { os.RemoveAll(scratch) })
	if err := os.MkdirAll(scratch, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(scratch, "doc.go"), []byte("package emittmp\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	dir := tamperFixture(t, func(lg map[string]any) {
		lg["head"] = "deadbeefdeadbeef"
	})
	var out bytes.Buffer
	if code := run([]string{"-emit-test", "zzrepro-emittest3", dir}, &out, io.Discard); code == 0 {
		t.Fatalf("tampered capture emitted with exit 0:\n%s", out.String())
	}
	if !strings.Contains(out.String(), "DIVERGED") {
		t.Errorf("output missing DIVERGED:\n%s", out.String())
	}
	if _, err := os.Stat(filepath.Join(scratch, "testdata")); !os.IsNotExist(err) {
		t.Errorf("tampered emit created testdata (stat err %v)", err)
	}
	if _, err := os.Stat(filepath.Join(scratch, "repro_feedback_"+sanitize(fixtureID)+"_test.go")); !os.IsNotExist(err) {
		t.Errorf("tampered emit wrote the skeleton (stat err %v)", err)
	}
}

// TestPrintSeatsShowsOpponentAuraOnItsHost: the view groups battlefields by
// controller, so an Aura seat 0 controls on seat 1's creature sits in seat
// 0's list while its host sits in seat 1's. The summary must print it on the
// host (naming its controller), and not drop it from both sections.
func TestPrintSeatsShowsOpponentAuraOnItsHost(t *testing.T) {
	players := []view.PlayerView{
		{ID: 0, Name: "Caster", Battlefield: []view.CardView{
			{ID: 10, Name: "Pacifism", AttachedTo: 20},
			{ID: 11, Name: "Plains"},
		}},
		{ID: 1, Name: "Target", Battlefield: []view.CardView{
			{ID: 20, Name: "Grizzly Bears", Power: 2, Toughness: 2},
			{ID: 21, Name: "Rancor", AttachedTo: 20},
		}},
	}
	var out bytes.Buffer
	printSeats(&out, players, false)
	got := out.String()
	if !strings.Contains(got, "Grizzly Bears (#20) 2/2, attachments: Pacifism (seat 0's), Rancor") {
		t.Errorf("host line does not list both attachments:\n%s", got)
	}
	if strings.Contains(got, "- Pacifism") || strings.Contains(got, "- Rancor") {
		t.Errorf("an attachment also printed as a standalone permanent:\n%s", got)
	}
	if !strings.Contains(got, "- Plains (#11)") {
		t.Errorf("unattached permanent missing:\n%s", got)
	}
}

// TestPrintSeatsKeepsAttachmentWithMissingHost: an attachment whose host is
// not in the view still prints, naming the host id, instead of vanishing.
func TestPrintSeatsKeepsAttachmentWithMissingHost(t *testing.T) {
	players := []view.PlayerView{{ID: 0, Name: "Solo", Battlefield: []view.CardView{
		{ID: 10, Name: "Bonesplitter", AttachedTo: 99},
	}}}
	var out bytes.Buffer
	printSeats(&out, players, false)
	if !strings.Contains(out.String(), "- Bonesplitter (#10) 0/0, attached to #99 (not on the battlefield)") {
		t.Errorf("orphaned attachment not printed:\n%s", out.String())
	}
}

// tamperFixture copies the committed fixture into a temp dir and rewrites
// its log.json through edit.
func tamperFixture(t *testing.T, edit func(map[string]any)) string {
	t.Helper()
	dir := t.TempDir()
	for _, f := range []string{"match.json", "view.json", "report.json"} {
		raw, err := os.ReadFile(filepath.Join(fixtureRel, f))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(dir, f), raw, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	raw, err := os.ReadFile(filepath.Join(fixtureRel, "log.json"))
	if err != nil {
		t.Fatal(err)
	}
	var lg map[string]any
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber() // preserve the uint64 seed exactly while editing another field
	if err := dec.Decode(&lg); err != nil {
		t.Fatal(err)
	}
	edit(lg)
	out, err := json.Marshal(lg)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "log.json"), out, 0o644); err != nil {
		t.Fatal(err)
	}
	return dir
}
